// Distribui os leads quentes entre os vendedores ativos.
// Regra: score >= 85 -> time enterprise; abaixo disso -> time smb.
// Dentro de cada time: rodízio (round-robin), lembrando de quem foi a vez.
const leads = $('Buscar leads quentes').all().map(i => i.json);
const reps  = $input.all().map(i => i.json);
if (!leads.length || !reps.length) return [];

const times = {
  enterprise: reps.filter(r => r.team === 'enterprise'),
  smb:        reps.filter(r => r.team === 'smb'),
};
const memoria = $getWorkflowStaticData('global');
memoria.vez = memoria.vez || { enterprise: 0, smb: 0 };

return leads.map(lead => {
  let time = lead.lead_score >= 85 ? 'enterprise' : 'smb';
  if (!times[time].length) time = time === 'enterprise' ? 'smb' : 'enterprise';
  const grupo = times[time].length ? times[time] : reps;
  const vendedor = grupo[memoria.vez[time] % grupo.length];
  memoria.vez[time]++;
  return { json: {
    lead_id:    lead.lead_id,
    lead_score: lead.lead_score,
    rep_id:     vendedor.rep_id,
    time,
    prioridade: lead.lead_score >= 85 ? 'ALTA' : 'NORMAL',
  }};
});
